#!/usr/bin/env bash
set -euo pipefail
sequence=34
echo "channel=kalmannet-daily-perbasin sequence=${sequence} purpose=v2-task6-isolated-deployment"
date --iso-8601=seconds
hostname
export PYTHONDONTWRITEBYTECODE=1
export OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 OPENBLAS_NUM_THREADS=4 NUMEXPR_NUM_THREADS=4
PYBIN=/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python
"$PYBIN" -B - "$sequence" <<'PY'
import base64,hashlib,io,json,pathlib,subprocess,sys,tarfile,os
sequence=int(sys.argv[1])
root=pathlib.Path('/data1/home/sunyiq/kalmannet_daily_camels_per_basin_pilots_20260901')
parent=root/'deployments'
assert root.is_dir() and root.resolve()==root and not root.is_symlink()
assert parent.is_dir() and parent.resolve()==parent and not parent.is_symlink()
dest=parent/f'DAILY_CAMELS_KNET_PER_BASIN_V2_BUNDLE_DEPLOY1_SEQ{sequence}'
assert not dest.exists() and not dest.is_symlink(), 'DEPLOYMENT_ALREADY_EXISTS'
data=base64.b64decode('',validate=True)
sha=lambda b:hashlib.sha256(b).hexdigest()
assert len(data)==438532 and sha(data)=='1b78bbae823d55859391a6cdee3b9fbe8a40203e5140b8795105a8617592b7fd'
with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as tar:
    members=tar.getmembers()
    names=[x.name for x in members]
    assert len(names)==len(set(names))==51
    for member in members:
        p=pathlib.PurePosixPath(member.name)
        assert member.isfile() and not member.issym() and not member.islnk()
        assert not p.is_absolute() and '..' not in p.parts and str(p)==member.name and '\\' not in member.name
    payload={x.name:tar.extractfile(x).read() for x in members}
manifest_bytes=payload['bundle_manifest.json']
assert sha(manifest_bytes)=='5abaa07cfc00e2795a91a8cd70bb793e5cf362971fd04a2de44cbf3e15fa587f'
manifest=json.loads(manifest_bytes)
assert len(manifest['member_sha256'])==manifest['member_count']==50
assert set(payload)==set(manifest['member_sha256'])|{'bundle_manifest.json'}
assert manifest['formal_evaluation_member_count']==manifest['historical_evaluation_member_count']==0
assert manifest['formal_evaluation_enabled'] is False and manifest['regional_training_enabled'] is False
for name,expected in manifest['member_sha256'].items():
    assert sha(payload[name])==expected and len(payload[name])==manifest['member_size_bytes'][name]
dest.mkdir()
with (dest/'daily_camels_knet_per_basin_pilots_v2.tar.gz').open('xb') as f:
    f.write(data);f.flush();os.fsync(f.fileno())
source=dest/'source';source.mkdir()
for name,content in sorted(payload.items()):
    path=source/pathlib.PurePosixPath(name)
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('xb') as f:
        f.write(content);f.flush();os.fsync(f.fileno())
actual={p.relative_to(source).as_posix():p for p in source.rglob('*') if p.is_file()}
assert set(actual)==set(payload) and len(actual)==51
assert all(not p.is_symlink() and p.read_bytes()==payload[name] for name,p in actual.items())
audit=subprocess.run([sys.executable,'-B',str(source/'scripts/build_daily_camels_knet_per_basin_hpc_bundle.py'),'--inspect-root',str(source)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False)
print(audit.stdout.decode('utf-8'),end='')
print(audit.stderr.decode('utf-8'),end='',file=sys.stderr)
assert audit.returncode==0, f'INSPECT_ROOT_EXIT_{audit.returncode}'
print(json.dumps({'status':'TASK6_DEPLOYMENT_PASS','request_sequence':sequence,'deployment_directory':str(dest),'source_root':str(source),'archive_bytes':len(data),'archive_sha256':sha(data),'internal_manifest_sha256':sha(manifest_bytes),'payload_members':50,'deployed_files_including_manifest':51,'member_mismatches':0,'formal_evaluation_member_count':0,'optimizer_steps':0,'training_submissions':0,'source_sha256_modified':False},sort_keys=True))
PY
